      pt: "Uma reserva costeira em Yucatán, mundialmente famosa pelas suas enormes colónias de flamingos cor-de-rosa.",
      fr: "Une réserve côtière au Yucatán, célèbre dans le monde entier pour ses immenses colonies de flamants roses.",
