      es: ["México es el principal exportador mundial de mangos frescos.", "Sinaloa produce anualmente más de 350,000 toneladas de esta fruta tropical.", "La variedad 'Ataulfo' es una raza puramente mexicana con textura cremosa.", "Los manguiers pueden vivir más de 100 años y seguir dando frutos.", "La temporada principal de cosecha en Sinaloa es entre mayo y agosto.", "Las modernas plantas de empaque en Sinaloa cumplen con los más altos estándares internacionales.", "Los mangos son ricos en vitamina A y C y un componente importante de la dieta local."],
