      fr: ["Le Mexique est le premier exportateur mondial de mangues fraîches.", "Sinaloa produit plus de 350 000 tonnes de ce fruit tropical par an.", "La variété 'Ataulfo' est une sélection purement mexicaine à la texture crémeuse.", "Les manguiers peuvent vivre plus de 100 ans et continuer à porter des fruits.", "La principale période de récolte à Sinaloa se situe entre mai et août.", "Les usines d'emballage modernes de Sinaloa respectent les normes internationales les plus strictes.", "Les mangues sont riches en vitamines A et C et constituent un élément important de l'alimentation locale."],
